TEST(materialx_usdshade_reader, reads_tiledimage_texture2d_family)
{
  const TemporaryImage image_asset;
  const pxr::UsdStageRefPtr stage = pxr::UsdStage::CreateInMemory();
  ASSERT_TRUE(stage);
  const pxr::UsdShadeMaterial material = pxr::UsdShadeMaterial::Define(
      stage, pxr::SdfPath("/Looks/TiledImage"));
  const auto shader = [&](const char *name) {
    return pxr::UsdShadeShader::Define(stage, material.GetPath().AppendChild(pxr::TfToken(name)));
  };

  pxr::UsdShadeShader surface = shader("OpenPBR");
  surface.CreateIdAttr(pxr::VtValue(pxr::TfToken("ND_open_pbr_surface_surfaceshader")));
  surface.CreateOutput(pxr::TfToken("out"), pxr::SdfValueTypeNames->Token);

  pxr::UsdShadeShader uv = shader("UV");
  uv.CreateIdAttr(pxr::VtValue(pxr::TfToken("ND_constant_vector2")));
  uv.CreateInput(pxr::TfToken("value"), pxr::SdfValueTypeNames->Float2).Set(pxr::GfVec2f(0.25f, 0.5f));
  uv.CreateOutput(pxr::TfToken("out"), pxr::SdfValueTypeNames->Float2);

  struct Case {
    const char *name;
    const char *nodedef;
    const pxr::SdfValueTypeName *type;
    materialx::Type graph_type;
  };
  const Case cases[] = {{"TileFloat", "ND_tiledimage_float", &pxr::SdfValueTypeNames->Float, materialx::Type::Float},
                        {"TileColor3", "ND_tiledimage_color3", &pxr::SdfValueTypeNames->Color3f, materialx::Type::Color3},
                        {"TileColor4", "ND_tiledimage_color4", &pxr::SdfValueTypeNames->Color4f, materialx::Type::Color4},
                        {"TileVector2", "ND_tiledimage_vector2", &pxr::SdfValueTypeNames->Float2, materialx::Type::Vector2},
                        {"TileVector3", "ND_tiledimage_vector3", &pxr::SdfValueTypeNames->Float3, materialx::Type::Vector3},
                        {"TileVector4", "ND_tiledimage_vector4", &pxr::SdfValueTypeNames->Float4, materialx::Type::Vector4}};

  for (const Case &item : cases) {
    pxr::UsdShadeShader tile = shader(item.name);
    tile.CreateIdAttr(pxr::VtValue(pxr::TfToken(item.nodedef)));
    tile.CreateInput(pxr::TfToken("file"), pxr::SdfValueTypeNames->Asset)
        .Set(pxr::SdfAssetPath(image_asset.path()));
    ASSERT_TRUE(tile.CreateInput(pxr::TfToken("texcoord"), pxr::SdfValueTypeNames->Float2)
                    .ConnectToSource(uv.ConnectableAPI(), pxr::TfToken("out")));
    tile.CreateInput(pxr::TfToken("uvtiling"), pxr::SdfValueTypeNames->Float2).Set(pxr::GfVec2f(2.0f, 3.0f));
    tile.CreateInput(pxr::TfToken("uvoffset"), pxr::SdfValueTypeNames->Float2).Set(pxr::GfVec2f(0.1f, 0.2f));
    tile.CreateInput(pxr::TfToken("realworldimagesize"), pxr::SdfValueTypeNames->Float2).Set(pxr::GfVec2f(4.0f, 5.0f));
    tile.CreateInput(pxr::TfToken("realworldtilesize"), pxr::SdfValueTypeNames->Float2).Set(pxr::GfVec2f(6.0f, 7.0f));
    tile.CreateInput(pxr::TfToken("filtertype"), pxr::SdfValueTypeNames->String).Set("cubic");
    tile.CreateInput(pxr::TfToken("framerange"), pxr::SdfValueTypeNames->String).Set("");
    tile.CreateInput(pxr::TfToken("frameoffset"), pxr::SdfValueTypeNames->Int).Set(0);
    tile.CreateInput(pxr::TfToken("frameendaction"), pxr::SdfValueTypeNames->String).Set("constant");
    pxr::UsdShadeInput fallback = tile.CreateInput(pxr::TfToken("default"), *item.type);
    if (item.graph_type == materialx::Type::Float) {
      fallback.Set(0.25f);
    }
    else if (item.graph_type == materialx::Type::Color3 || item.graph_type == materialx::Type::Vector3) {
      fallback.Set(pxr::GfVec3f(0.1f, 0.2f, 0.3f));
    }
    else if (item.graph_type == materialx::Type::Vector2) {
      fallback.Set(pxr::GfVec2f(0.1f, 0.2f));
    }
    else {
      fallback.Set(pxr::GfVec4f(0.1f, 0.2f, 0.3f, 0.4f));
    }
    tile.CreateOutput(pxr::TfToken("out"), *item.type);
  }

  pxr::UsdShadeShader convert = shader("TileVector3Color");
  convert.CreateIdAttr(pxr::VtValue(pxr::TfToken("ND_convert_vector3_color3")));
  ASSERT_TRUE(convert.CreateInput(pxr::TfToken("in"), pxr::SdfValueTypeNames->Float3)
                  .ConnectToSource(shader("TileVector3").ConnectableAPI(), pxr::TfToken("out")));
  convert.CreateOutput(pxr::TfToken("out"), pxr::SdfValueTypeNames->Color3f);

  const auto connect_conversion = [&](const char *name, const char *id, const char *tile,
                                      const pxr::SdfValueTypeName &input_type, const char *port) {
    pxr::UsdShadeShader conv = shader(name);
    conv.CreateIdAttr(pxr::VtValue(pxr::TfToken(id)));
    EXPECT_TRUE(conv.CreateInput(pxr::TfToken("in"), input_type)
                    .ConnectToSource(shader(tile).ConnectableAPI(), pxr::TfToken("out")));
    conv.CreateOutput(pxr::TfToken("out"), pxr::SdfValueTypeNames->Color3f);
    EXPECT_TRUE(surface.CreateInput(pxr::TfToken(port), pxr::SdfValueTypeNames->Color3f)
                    .ConnectToSource(conv.ConnectableAPI(), pxr::TfToken("out")));
  };
  connect_conversion("Color4RGB", "ND_convert_color4_color3", "TileColor4",
                     pxr::SdfValueTypeNames->Color4f, "coat_color");
  connect_conversion("Vector4RGB", "ND_convert_vector4_color3", "TileVector4",
                     pxr::SdfValueTypeNames->Float4, "fuzz_color");
  pxr::UsdShadeShader extract = shader("Vector2X");
  extract.CreateIdAttr(pxr::VtValue(pxr::TfToken("ND_extract_vector2")));
  ASSERT_TRUE(extract.CreateInput(pxr::TfToken("in"), pxr::SdfValueTypeNames->Float2)
                  .ConnectToSource(shader("TileVector2").ConnectableAPI(), pxr::TfToken("out")));
  extract.CreateInput(pxr::TfToken("index"), pxr::SdfValueTypeNames->Int).Set(0);
  extract.CreateOutput(pxr::TfToken("out"), pxr::SdfValueTypeNames->Float);
  ASSERT_TRUE(surface.CreateInput(pxr::TfToken("specular_roughness"), pxr::SdfValueTypeNames->Float)
                  .ConnectToSource(extract.ConnectableAPI(), pxr::TfToken("out")));

  ASSERT_TRUE(surface.CreateInput(pxr::TfToken("base_weight"), pxr::SdfValueTypeNames->Float)
                  .ConnectToSource(shader("TileFloat").ConnectableAPI(), pxr::TfToken("out")));
  ASSERT_TRUE(surface.CreateInput(pxr::TfToken("base_color"), pxr::SdfValueTypeNames->Color3f)
                  .ConnectToSource(shader("TileColor3").ConnectableAPI(), pxr::TfToken("out")));
  ASSERT_TRUE(surface.CreateInput(pxr::TfToken("emission_color"), pxr::SdfValueTypeNames->Color3f)
                  .ConnectToSource(convert.ConnectableAPI(), pxr::TfToken("out")));
  const pxr::TfToken context("mtlx", pxr::TfToken::Immortal);
  ASSERT_TRUE(material.CreateSurfaceOutput(context).ConnectToSource(surface.ConnectableAPI(),
                                                                    pxr::TfToken("out")));

  materialx::Graph graph;
  string error;
  ASSERT_TRUE(materialx::read_usdshade_graph(material, &graph, &error)) << error;
  int tiled_count = 0;
  for (const materialx::Node &node : graph.nodes) {
    if (node.nodedef.find("ND_tiledimage_") == 0) {
      ++tiled_count;
      EXPECT_EQ(node.links.at("texcoord").type, materialx::Type::Vector2);
      EXPECT_EQ(node.vector2_inputs.at("uvtiling"), make_float2(2.0f, 3.0f));
      EXPECT_EQ(node.vector2_inputs.at("realworldtilesize"), make_float2(6.0f, 7.0f));
      EXPECT_EQ(node.string_inputs.at("filtertype"), "cubic");
    }
  }
  EXPECT_EQ(tiled_count, 6);

  ShaderGraph lowered;
  ASSERT_TRUE(materialx::lower(graph, &lowered));
  std::unordered_map<string, ShaderNode *> nodes;
  for (ShaderNode *node : lowered.nodes) {
    nodes[node->name.string()] = node;
  }
  ASSERT_NE(nodes["TileFloat.tile"], nullptr);
  EXPECT_EQ(static_cast<VectorMathNode *>(nodes["TileFloat.tile"])->get_math_type(),
            NODE_VECTOR_MATH_MULTIPLY);
  ASSERT_NE(nodes["TileFloat.image"], nullptr);
  EXPECT_EQ(static_cast<ImageTextureNode *>(nodes["TileFloat.image"])->get_interpolation(),
            INTERPOLATION_CUBIC);
  ASSERT_NE(nodes["TileColor3.tile_size"], nullptr);
  ASSERT_NE(nodes["TileVector3"], nullptr);
  ASSERT_NE(nodes["TileColor4"], nullptr);
  ASSERT_NE(nodes["TileVector2.image"], nullptr);
  ASSERT_NE(nodes["TileVector4"], nullptr);
}

TEST(materialx_usdshade_reader, tiledimage_float_linked_controls_file_priority_and_empty_default)
{
  const TemporaryImage image_asset;
  for (const string mode : {"nonempty", "nonempty_dot", "empty_literal", "empty_constant", "empty_dot", "empty_dot_no_note", "image_empty_constant", "image_empty_dot"}) {
    SCOPED_TRACE(mode);
    const bool empty_file = mode.find("nonempty") != 0;
    const bool image_consumer = mode.find("image_empty") == 0;
    const auto stage = pxr::UsdStage::CreateInMemory();
    const auto material = pxr::UsdShadeMaterial::Define(stage, pxr::SdfPath("/Looks/Test"));
    const auto shader = [&](const char *name, const char *id, const pxr::SdfValueTypeName &type) {
      auto node = pxr::UsdShadeShader::Define(stage, material.GetPath().AppendChild(pxr::TfToken(name)));
      node.CreateIdAttr(pxr::VtValue(pxr::TfToken(id)));
      node.CreateOutput(pxr::TfToken("out"), type);
      return node;
    };
    auto tile = shader("Tile", image_consumer ? "ND_tiledimage_color3" : "ND_tiledimage_float",
                       image_consumer ? pxr::SdfValueTypeNames->Color3f : pxr::SdfValueTypeNames->Float);
    auto file = tile.CreateInput(pxr::TfToken("file"), pxr::SdfValueTypeNames->Asset);
    file.Set(pxr::SdfAssetPath(empty_file ? "" : "unused-fallback.ppm"));
    if (mode != "empty_literal") {
      const bool dot = mode.find("dot") != string::npos;
      auto filename = shader("Filename", dot ? "ND_dot_filename" : "ND_constant_filename", pxr::SdfValueTypeNames->Asset);
      filename.CreateInput(pxr::TfToken(dot ? "in" : "value"), pxr::SdfValueTypeNames->Asset)
          .Set(pxr::SdfAssetPath(empty_file ? "" : image_asset.path()));
      if (dot && mode != "empty_dot_no_note") filename.CreateInput(pxr::TfToken("note"), pxr::SdfValueTypeNames->String).Set("note");
      ASSERT_TRUE(file.ConnectToSource(filename.ConnectableAPI(), pxr::TfToken("out")));
    }
    if (image_consumer) tile.CreateInput(pxr::TfToken("default"), pxr::SdfValueTypeNames->Color3f).Set(pxr::GfVec3f(0.375f));
    else tile.CreateInput(pxr::TfToken("default"), pxr::SdfValueTypeNames->Float).Set(0.375f);
    const char *ports[] = {"texcoord", "uvtiling", "uvoffset", "realworldimagesize", "realworldtilesize"};
    for (int i = 0; i < 5; i++) {
      auto source = shader((string("UV") + std::to_string(i)).c_str(), "ND_constant_vector2", pxr::SdfValueTypeNames->Float2);
      source.CreateInput(pxr::TfToken("value"), pxr::SdfValueTypeNames->Float2).Set(pxr::GfVec2f(float(i + 1), float(i + 2)));
      ASSERT_TRUE(tile.CreateInput(pxr::TfToken(ports[i]), pxr::SdfValueTypeNames->Float2)
                      .ConnectToSource(source.ConnectableAPI(), pxr::TfToken("out")));
    }
    tile.CreateInput(pxr::TfToken("filtertype"), pxr::SdfValueTypeNames->String).Set("linear");
    tile.CreateInput(pxr::TfToken("framerange"), pxr::SdfValueTypeNames->String).Set("");
    tile.CreateInput(pxr::TfToken("frameoffset"), pxr::SdfValueTypeNames->Int).Set(0);
    tile.CreateInput(pxr::TfToken("frameendaction"), pxr::SdfValueTypeNames->String).Set("constant");
    auto surface = shader("Surface", "ND_open_pbr_surface_surfaceshader", pxr::SdfValueTypeNames->Token);
    ASSERT_TRUE(surface.CreateInput(pxr::TfToken(image_consumer ? "base_color" : "base_weight"),
                                  image_consumer ? pxr::SdfValueTypeNames->Color3f : pxr::SdfValueTypeNames->Float)
                    .ConnectToSource(tile.ConnectableAPI(), pxr::TfToken("out")));
    ASSERT_TRUE(material.CreateSurfaceOutput(pxr::TfToken("mtlx")).ConnectToSource(surface.ConnectableAPI(), pxr::TfToken("out")));
    materialx::Graph graph;
    string error;
    const bool read = materialx::read_usdshade_graph(material, &graph, &error);
    if (mode == "empty_dot_no_note") {
      EXPECT_FALSE(read);
      EXPECT_NE(error.find("exact required signature"), string::npos);
      continue;
    }
    if (image_consumer) {
      EXPECT_FALSE(read);
      EXPECT_NE(error.find("non-empty literal filename"), string::npos);
      continue;
    }
    ASSERT_TRUE(read) << error;
    const materialx::Node *target = nullptr;
    for (const auto &node : graph.nodes) if (node.name == "Tile") target = &node;
    ASSERT_NE(target, nullptr);
    if (empty_file) {
      EXPECT_EQ(target->nodedef, "ND_constant_float");
      EXPECT_FLOAT_EQ(target->inputs.at("value"), 0.375f);
    }
    else {
      EXPECT_EQ(target->asset_inputs.at("file"), image_asset.path());
      for (const char *port : ports) EXPECT_EQ(target->links.at(port).type, materialx::Type::Vector2);
    }
    ASSERT_TRUE(materialx::validate(graph));
    ShaderGraph lowered;
    ASSERT_TRUE(materialx::lower(graph, &lowered, &error)) << error;
    if (!empty_file) {
      const auto find = [&](const char *suffix) -> VectorMathNode * {
        for (ShaderNode *node : lowered.nodes)
          if (node->name == string("Tile.") + suffix) return dynamic_cast<VectorMathNode *>(node);
        return nullptr;
      };
      auto *tile_node = find("tile"), *offset = find("offset"), *image_size = find("image_size"), *tile_size = find("tile_size");
      ASSERT_NE(tile_node, nullptr); ASSERT_NE(offset, nullptr); ASSERT_NE(image_size, nullptr); ASSERT_NE(tile_size, nullptr);
      EXPECT_EQ(tile_node->get_math_type(), NODE_VECTOR_MATH_MULTIPLY);
      EXPECT_EQ(offset->get_math_type(), NODE_VECTOR_MATH_SUBTRACT);
      EXPECT_EQ(image_size->get_math_type(), NODE_VECTOR_MATH_DIVIDE);
      EXPECT_EQ(tile_size->get_math_type(), NODE_VECTOR_MATH_MULTIPLY);
      EXPECT_NE(tile_node->input("Vector1")->link, nullptr);
      EXPECT_EQ(offset->input("Vector1")->link, tile_node->output("Vector"));
      EXPECT_EQ(image_size->input("Vector1")->link, offset->output("Vector"));
      EXPECT_EQ(tile_size->input("Vector1")->link, image_size->output("Vector"));
      for (auto *node : {tile_node, offset, image_size, tile_size}) EXPECT_NE(node->input("Vector2")->link, nullptr);
    }
  }
}

TEST(materialx_usdshade_reader, reads_image_color3_canonical_sampling_controls)
{
  const TemporaryImage image_asset;
  const pxr::UsdStageRefPtr stage = pxr::UsdStage::CreateInMemory();
  ASSERT_TRUE(stage);
  const pxr::UsdShadeMaterial material = pxr::UsdShadeMaterial::Define(
      stage, pxr::SdfPath("/Looks/ImageColor3"));
  const auto shader = [&](const char *name) {
    return pxr::UsdShadeShader::Define(stage, material.GetPath().AppendChild(pxr::TfToken(name)));
  };

  pxr::UsdShadeShader uv = shader("UV");
  uv.CreateIdAttr(pxr::VtValue(pxr::TfToken("ND_constant_vector2")));
  uv.CreateInput(pxr::TfToken("value"), pxr::SdfValueTypeNames->Float2)
      .Set(pxr::GfVec2f(0.25f, 0.5f));
  uv.CreateOutput(pxr::TfToken("out"), pxr::SdfValueTypeNames->Float2);

  pxr::UsdShadeShader image = shader("Image");
  image.CreateIdAttr(pxr::VtValue(pxr::TfToken("ND_image_color3")));
  image.CreateInput(pxr::TfToken("file"), pxr::SdfValueTypeNames->Asset)
      .Set(pxr::SdfAssetPath(image_asset.path()));
  image.CreateInput(pxr::TfToken("layer"), pxr::SdfValueTypeNames->String).Set("");
  image.CreateInput(pxr::TfToken("default"), pxr::SdfValueTypeNames->Color3f)
      .Set(pxr::GfVec3f(0.0f, 0.0f, 0.0f));
  ASSERT_TRUE(image.CreateInput(pxr::TfToken("texcoord"), pxr::SdfValueTypeNames->Float2)
                  .ConnectToSource(uv.ConnectableAPI(), pxr::TfToken("out")));
  image.CreateInput(pxr::TfToken("uaddressmode"), pxr::SdfValueTypeNames->String).Set("periodic");
  image.CreateInput(pxr::TfToken("vaddressmode"), pxr::SdfValueTypeNames->String).Set("periodic");
  image.CreateInput(pxr::TfToken("filtertype"), pxr::SdfValueTypeNames->String).Set("closest");
  image.CreateInput(pxr::TfToken("framerange"), pxr::SdfValueTypeNames->String).Set("");
  image.CreateInput(pxr::TfToken("frameoffset"), pxr::SdfValueTypeNames->Int).Set(0);
  image.CreateInput(pxr::TfToken("frameendaction"), pxr::SdfValueTypeNames->String)
      .Set("constant");
  image.CreateOutput(pxr::TfToken("out"), pxr::SdfValueTypeNames->Color3f);

  pxr::UsdShadeShader surface = shader("OpenPBR");
  surface.CreateIdAttr(pxr::VtValue(pxr::TfToken("ND_open_pbr_surface_surfaceshader")));
  ASSERT_TRUE(surface.CreateInput(pxr::TfToken("base_color"), pxr::SdfValueTypeNames->Color3f)
                  .ConnectToSource(image.ConnectableAPI(), pxr::TfToken("out")));
  surface.CreateOutput(pxr::TfToken("out"), pxr::SdfValueTypeNames->Token);
  const pxr::TfToken context("mtlx", pxr::TfToken::Immortal);
  ASSERT_TRUE(material.CreateSurfaceOutput(context).ConnectToSource(surface.ConnectableAPI(),
                                                                    pxr::TfToken("out")));

  materialx::Graph graph;
  string error;
  ASSERT_TRUE(materialx::read_usdshade_graph(material, &graph, &error)) << error;
  const auto image_node = std::find_if(
      graph.nodes.begin(), graph.nodes.end(), [](const materialx::Node &node) {
        return node.name == "Image";
      });
  ASSERT_NE(image_node, graph.nodes.end());
  EXPECT_EQ(image_node->asset_inputs.at("file"), image_asset.path());
  EXPECT_EQ(image_node->links.at("texcoord").type, materialx::Type::Vector2);
  EXPECT_EQ(image_node->color3_inputs.at("default"), zero_float3());
  EXPECT_EQ(image_node->string_inputs.at("filtertype"), "closest");
  EXPECT_EQ(image_node->string_inputs.at("addressmode"), "periodic");
  EXPECT_EQ(image_node->string_inputs.at("colorspace"), "");

  ASSERT_TRUE(image.GetInput(pxr::TfToken("uaddressmode")).Set("clamp"));
  ASSERT_TRUE(image.GetInput(pxr::TfToken("vaddressmode")).Set("clamp"));
  materialx::Graph clamp_graph;
  ASSERT_TRUE(materialx::read_usdshade_graph(material, &clamp_graph, &error)) << error;
  const auto clamp_image = std::find_if(
      clamp_graph.nodes.begin(), clamp_graph.nodes.end(), [](const materialx::Node &node) {
        return node.name == "Image";
      });
  ASSERT_NE(clamp_image, clamp_graph.nodes.end());
  EXPECT_EQ(clamp_image->string_inputs.at("addressmode"), "clamp");
}

TEST(materialx_usdshade_reader, image_color3_implicit_uv0_and_literal_coordinates)
{
  const TemporaryImage image_asset;
  const pxr::UsdStageRefPtr stage = pxr::UsdStage::CreateInMemory();
  ASSERT_TRUE(stage);
  const pxr::UsdShadeMaterial material = pxr::UsdShadeMaterial::Define(
      stage, pxr::SdfPath("/Looks/ImageColor3"));
  const auto shader = [&](const char *name) {
    return pxr::UsdShadeShader::Define(stage, material.GetPath().AppendChild(pxr::TfToken(name)));
  };

  pxr::UsdShadeShader uv = shader("UV");
  uv.CreateIdAttr(pxr::VtValue(pxr::TfToken("ND_constant_vector2")));
  uv.CreateInput(pxr::TfToken("value"), pxr::SdfValueTypeNames->Float2)
      .Set(pxr::GfVec2f(0.25f, 0.5f));
  uv.CreateOutput(pxr::TfToken("out"), pxr::SdfValueTypeNames->Float2);

  pxr::UsdShadeShader image = shader("Image");
  image.CreateIdAttr(pxr::VtValue(pxr::TfToken("ND_image_color3")));
  image.CreateInput(pxr::TfToken("file"), pxr::SdfValueTypeNames->Asset)
      .Set(pxr::SdfAssetPath(image_asset.path()));
  image.CreateInput(pxr::TfToken("layer"), pxr::SdfValueTypeNames->String).Set("");
  image.CreateInput(pxr::TfToken("default"), pxr::SdfValueTypeNames->Color3f)
      .Set(pxr::GfVec3f(0.0f, 0.0f, 0.0f));
  ASSERT_TRUE(image.CreateInput(pxr::TfToken("texcoord"), pxr::SdfValueTypeNames->Float2)
                  .ConnectToSource(uv.ConnectableAPI(), pxr::TfToken("out")));
  image.CreateInput(pxr::TfToken("uaddressmode"), pxr::SdfValueTypeNames->String).Set("periodic");
  image.CreateInput(pxr::TfToken("vaddressmode"), pxr::SdfValueTypeNames->String).Set("periodic");
  image.CreateInput(pxr::TfToken("filtertype"), pxr::SdfValueTypeNames->String).Set("closest");
  image.CreateInput(pxr::TfToken("framerange"), pxr::SdfValueTypeNames->String).Set("");
  image.CreateInput(pxr::TfToken("frameoffset"), pxr::SdfValueTypeNames->Int).Set(0);
  image.CreateInput(pxr::TfToken("frameendaction"), pxr::SdfValueTypeNames->String)
      .Set("constant");
  image.CreateOutput(pxr::TfToken("out"), pxr::SdfValueTypeNames->Color3f);

  pxr::UsdShadeShader surface = shader("OpenPBR");
  surface.CreateIdAttr(pxr::VtValue(pxr::TfToken("ND_open_pbr_surface_surfaceshader")));
  ASSERT_TRUE(surface.CreateInput(pxr::TfToken("base_color"), pxr::SdfValueTypeNames->Color3f)
                  .ConnectToSource(image.ConnectableAPI(), pxr::TfToken("out")));
  surface.CreateOutput(pxr::TfToken("out"), pxr::SdfValueTypeNames->Token);
  const pxr::TfToken context("mtlx", pxr::TfToken::Immortal);
  ASSERT_TRUE(material.CreateSurfaceOutput(context).ConnectToSource(surface.ConnectableAPI(),
                                                                    pxr::TfToken("out")));

  auto texcoord_input = image.GetInput(pxr::TfToken("texcoord"));
  texcoord_input.ClearSources();
  texcoord_input.GetAttr().Clear();
  for (int variant = 0; variant < 3; ++variant) {
    if (variant == 1) {
      image.GetPrim().RemoveProperty(pxr::TfToken("inputs:texcoord"));
    }
    else if (variant == 2) {
      texcoord_input = image.CreateInput(pxr::TfToken("texcoord"), pxr::SdfValueTypeNames->Float2);
      texcoord_input.Set(pxr::GfVec2f(0.25f, 0.75f));
    }
    materialx::Graph graph;
    string error;
    ASSERT_TRUE(materialx::read_usdshade_graph(material, &graph, &error)) << error;
    const auto image_node = std::find_if(
        graph.nodes.begin(), graph.nodes.end(), [](const materialx::Node &node) {
          return node.name == "Image";
        });
    ASSERT_NE(image_node, graph.nodes.end());
    const string uv_name = image_node->links.at("texcoord").source_node;
    const auto uv_node = std::find_if(
        graph.nodes.begin(), graph.nodes.end(), [&](const materialx::Node &node) {
          return node.name == uv_name;
        });
    ASSERT_NE(uv_node, graph.nodes.end());
    if (variant < 2) {
      EXPECT_EQ(uv_node->nodedef, "ND_geompropvalue_vector2");
      EXPECT_EQ(uv_node->string_inputs.at("geomprop"), "");
    }
    else {
      EXPECT_EQ(uv_node->nodedef, "ND_constant_vector2");
      EXPECT_EQ(uv_node->vector2_inputs.at("value"), make_float2(0.25f, 0.75f));
    }
    ShaderGraph lowered;
    EXPECT_TRUE(materialx::lower(graph, &lowered, &error)) << error;
  }
  texcoord_input.Set(pxr::GfVec2f(std::numeric_limits<float>::infinity(), 0.0f));
  materialx::Graph rejected;
  string error;
  EXPECT_FALSE(materialx::read_usdshade_graph(material, &rejected, &error));
}

TEST(materialx_usdshade_reader, reads_image_color3_unvalued_descriptor_defaults)
{
  const TemporaryImage image_asset;
  const pxr::UsdStageRefPtr stage = pxr::UsdStage::CreateInMemory();
  ASSERT_TRUE(stage);
  const pxr::UsdShadeMaterial material = pxr::UsdShadeMaterial::Define(
      stage, pxr::SdfPath("/Looks/ImageColor3Defaults"));
  const auto shader = [&](const char *name) {
    return pxr::UsdShadeShader::Define(stage, material.GetPath().AppendChild(pxr::TfToken(name)));
  };

  pxr::UsdShadeShader uv = shader("UV");
  uv.CreateIdAttr(pxr::VtValue(pxr::TfToken("ND_constant_vector2")));
  uv.CreateInput(pxr::TfToken("value"), pxr::SdfValueTypeNames->Float2)
      .Set(pxr::GfVec2f(0.25f, 0.5f));
  uv.CreateOutput(pxr::TfToken("out"), pxr::SdfValueTypeNames->Float2);

  pxr::UsdShadeShader image = shader("Image");
  image.CreateIdAttr(pxr::VtValue(pxr::TfToken("ND_image_color3")));
  image.CreateInput(pxr::TfToken("file"), pxr::SdfValueTypeNames->Asset)
      .Set(pxr::SdfAssetPath(image_asset.path()));
  image.CreateInput(pxr::TfToken("layer"), pxr::SdfValueTypeNames->String);
  image.CreateInput(pxr::TfToken("default"), pxr::SdfValueTypeNames->Color3f);
  ASSERT_TRUE(image.CreateInput(pxr::TfToken("texcoord"), pxr::SdfValueTypeNames->Float2)
                  .ConnectToSource(uv.ConnectableAPI(), pxr::TfToken("out")));
  image.CreateInput(pxr::TfToken("uaddressmode"), pxr::SdfValueTypeNames->String);
  image.CreateInput(pxr::TfToken("vaddressmode"), pxr::SdfValueTypeNames->String);
  image.CreateInput(pxr::TfToken("filtertype"), pxr::SdfValueTypeNames->String);
  image.CreateInput(pxr::TfToken("framerange"), pxr::SdfValueTypeNames->String);
  image.CreateInput(pxr::TfToken("frameoffset"), pxr::SdfValueTypeNames->Int);
  image.CreateInput(pxr::TfToken("frameendaction"), pxr::SdfValueTypeNames->String);
  image.CreateOutput(pxr::TfToken("out"), pxr::SdfValueTypeNames->Color3f);
  image.GetInput(pxr::TfToken("file")).GetAttr().SetColorSpace(pxr::TfToken("srgb_texture"));

  pxr::UsdShadeShader surface = shader("OpenPBR");
  surface.CreateIdAttr(pxr::VtValue(pxr::TfToken("ND_open_pbr_surface_surfaceshader")));
  ASSERT_TRUE(surface.CreateInput(pxr::TfToken("base_color"), pxr::SdfValueTypeNames->Color3f)
                  .ConnectToSource(image.ConnectableAPI(), pxr::TfToken("out")));
  surface.CreateOutput(pxr::TfToken("out"), pxr::SdfValueTypeNames->Token);
  const pxr::TfToken context("mtlx", pxr::TfToken::Immortal);
  ASSERT_TRUE(material.CreateSurfaceOutput(context).ConnectToSource(surface.ConnectableAPI(),
                                                                    pxr::TfToken("out")));

  materialx::Graph graph;
  string error;
  ASSERT_TRUE(materialx::read_usdshade_graph(material, &graph, &error)) << error;
  const auto image_node = std::find_if(
      graph.nodes.begin(), graph.nodes.end(), [](const materialx::Node &node) {
        return node.name == "Image";
      });
  ASSERT_NE(image_node, graph.nodes.end());
  EXPECT_EQ(image_node->color3_inputs.at("default"), zero_float3());
  EXPECT_EQ(image_node->string_inputs.at("filtertype"), "linear");
  EXPECT_EQ(image_node->string_inputs.at("addressmode"), "periodic");
  EXPECT_EQ(image_node->string_inputs.at("colorspace"), "srgb_texture");
  for (const char *color_space : {"raw", "lin_rec709"}) {
    image.GetInput(pxr::TfToken("file")).GetAttr().SetColorSpace(pxr::TfToken(color_space));
    materialx::Graph next_graph;
    ASSERT_TRUE(materialx::read_usdshade_graph(material, &next_graph, &error)) << error;
    const auto found = std::find_if(
        next_graph.nodes.begin(), next_graph.nodes.end(), [](const materialx::Node &node) {
          return node.name == "Image";
        });
    ASSERT_NE(found, next_graph.nodes.end());
    EXPECT_EQ(found->string_inputs.at("colorspace"), color_space);
  }
  image.GetInput(pxr::TfToken("file")).GetAttr().SetColorSpace(pxr::TfToken("unsupported_space"));
  materialx::Graph rejected_graph;
  EXPECT_FALSE(materialx::read_usdshade_graph(material, &rejected_graph, &error));
  EXPECT_NE(error.find("unsupported authored colorspace"), string::npos) << error;
  image.GetInput(pxr::TfToken("file")).GetAttr().SetColorSpace(pxr::TfToken("raw"));
  image.GetOutput(pxr::TfToken("out")).GetAttr().SetColorSpace(pxr::TfToken("srgb_texture"));
  EXPECT_FALSE(materialx::read_usdshade_graph(material, &rejected_graph, &error));
  EXPECT_NE(error.find("output colorspace transforms"), string::npos) << error;
}

TEST(materialx_usdshade_reader, rejects_unsupported_image_color3_controls)
{
  const TemporaryImage image_asset;
  const auto expect_rejected = [&](const char *edit_input,
                                   const pxr::VtValue &value,
                                   const char *expected_error) {
    const pxr::UsdStageRefPtr stage = pxr::UsdStage::CreateInMemory();
    ASSERT_TRUE(stage);
    const pxr::UsdShadeMaterial material = pxr::UsdShadeMaterial::Define(
        stage, pxr::SdfPath("/Looks/ImageColor3Reject"));
    const auto shader = [&](const char *name) {
      return pxr::UsdShadeShader::Define(stage,
                                         material.GetPath().AppendChild(pxr::TfToken(name)));
    };

    pxr::UsdShadeShader uv = shader("UV");
    uv.CreateIdAttr(pxr::VtValue(pxr::TfToken("ND_constant_vector2")));
    uv.CreateInput(pxr::TfToken("value"), pxr::SdfValueTypeNames->Float2)
        .Set(pxr::GfVec2f(0.25f, 0.5f));
    uv.CreateOutput(pxr::TfToken("out"), pxr::SdfValueTypeNames->Float2);

    pxr::UsdShadeShader image = shader("Image");
    image.CreateIdAttr(pxr::VtValue(pxr::TfToken("ND_image_color3")));
    image.CreateInput(pxr::TfToken("file"), pxr::SdfValueTypeNames->Asset)
        .Set(pxr::SdfAssetPath(image_asset.path()));
    image.CreateInput(pxr::TfToken("layer"), pxr::SdfValueTypeNames->String).Set("");
    image.CreateInput(pxr::TfToken("default"), pxr::SdfValueTypeNames->Color3f)
        .Set(pxr::GfVec3f(0.0f, 0.0f, 0.0f));
    ASSERT_TRUE(image.CreateInput(pxr::TfToken("texcoord"), pxr::SdfValueTypeNames->Float2)
                    .ConnectToSource(uv.ConnectableAPI(), pxr::TfToken("out")));
    image.CreateInput(pxr::TfToken("uaddressmode"), pxr::SdfValueTypeNames->String)
        .Set("periodic");
    image.CreateInput(pxr::TfToken("vaddressmode"), pxr::SdfValueTypeNames->String)
        .Set("periodic");
    image.CreateInput(pxr::TfToken("filtertype"), pxr::SdfValueTypeNames->String).Set("linear");
    image.CreateInput(pxr::TfToken("framerange"), pxr::SdfValueTypeNames->String).Set("");
    image.CreateInput(pxr::TfToken("frameoffset"), pxr::SdfValueTypeNames->Int).Set(0);
    image.CreateInput(pxr::TfToken("frameendaction"), pxr::SdfValueTypeNames->String)
        .Set("constant");
    image.CreateOutput(pxr::TfToken("out"), pxr::SdfValueTypeNames->Color3f);
    ASSERT_TRUE(image.GetInput(pxr::TfToken(edit_input)).Set(value));

    pxr::UsdShadeShader surface = shader("OpenPBR");
    surface.CreateIdAttr(pxr::VtValue(pxr::TfToken("ND_open_pbr_surface_surfaceshader")));
    ASSERT_TRUE(surface.CreateInput(pxr::TfToken("base_color"), pxr::SdfValueTypeNames->Color3f)
                    .ConnectToSource(image.ConnectableAPI(), pxr::TfToken("out")));
    surface.CreateOutput(pxr::TfToken("out"), pxr::SdfValueTypeNames->Token);
    const pxr::TfToken context("mtlx", pxr::TfToken::Immortal);
    ASSERT_TRUE(material.CreateSurfaceOutput(context).ConnectToSource(surface.ConnectableAPI(),
                                                                      pxr::TfToken("out")));

    materialx::Graph graph;
    string error;
    EXPECT_FALSE(materialx::read_usdshade_graph(material, &graph, &error));
    EXPECT_NE(error.find(expected_error), string::npos) << error;
  };

  expect_rejected("filtertype", pxr::VtValue(string("cubic")), "closest' or 'linear");
  expect_rejected("uaddressmode", pxr::VtValue(string("clamp")), "matching u/v address modes");
  expect_rejected("vaddressmode", pxr::VtValue(string("mirror")), "matching u/v address modes");
  expect_rejected("layer", pxr::VtValue(string("beauty")), "unsupported layer");
  expect_rejected("frameoffset", pxr::VtValue(1), "frameoffset 0");
  expect_rejected("default", pxr::VtValue(pxr::GfVec3f(0.1f, 0.0f, 0.0f)), "zero default");
}

TEST(materialx_usdshade_reader, reads_color3_scalar_math_literal_operands)
{
  const pxr::UsdStageRefPtr stage = pxr::UsdStage::CreateInMemory();
  ASSERT_TRUE(stage);
  const pxr::UsdShadeMaterial material = pxr::UsdShadeMaterial::Define(
      stage, pxr::SdfPath("/Looks/Color3ScalarMath"));
  const auto shader = [&](const char *name) {
    return pxr::UsdShadeShader::Define(stage, material.GetPath().AppendChild(pxr::TfToken(name)));
  };

  pxr::UsdShadeShader math = shader("Add");
  math.CreateIdAttr(pxr::VtValue(pxr::TfToken("ND_add_color3FA")));
  math.CreateInput(pxr::TfToken("in1"), pxr::SdfValueTypeNames->Color3f)
      .Set(pxr::GfVec3f(0.25f, 0.5f, 0.75f));
  math.CreateInput(pxr::TfToken("in2"), pxr::SdfValueTypeNames->Float).Set(2.0f);
  math.CreateOutput(pxr::TfToken("out"), pxr::SdfValueTypeNames->Color3f);

  pxr::UsdShadeShader surface = shader("OpenPBR");
  surface.CreateIdAttr(pxr::VtValue(pxr::TfToken("ND_open_pbr_surface_surfaceshader")));
  ASSERT_TRUE(surface.CreateInput(pxr::TfToken("base_color"), pxr::SdfValueTypeNames->Color3f)
                  .ConnectToSource(math.ConnectableAPI(), pxr::TfToken("out")));
  surface.CreateOutput(pxr::TfToken("out"), pxr::SdfValueTypeNames->Token);
  const pxr::TfToken context("mtlx", pxr::TfToken::Immortal);
  ASSERT_TRUE(material.CreateSurfaceOutput(context).ConnectToSource(surface.ConnectableAPI(),
                                                                    pxr::TfToken("out")));

  materialx::Graph graph;
  string error;
  ASSERT_TRUE(materialx::read_usdshade_graph(material, &graph, &error)) << error;
  const auto read_math = std::find_if(graph.nodes.begin(), graph.nodes.end(), [](const materialx::Node &node) {
    return node.name == "Add";
  });
  ASSERT_NE(read_math, graph.nodes.end());
  EXPECT_EQ(read_math->color3_inputs.at("in1"), make_float3(0.25f, 0.5f, 0.75f));
  EXPECT_FLOAT_EQ(read_math->inputs.at("in2"), 2.0f);
  EXPECT_TRUE(read_math->links.empty());

  ShaderGraph lowered;
  ASSERT_TRUE(materialx::lower(graph, &lowered));
}

TEST(materialx_usdshade_reader, reads_separate2_vector2_literal_operand)
{
  const pxr::UsdStageRefPtr stage = pxr::UsdStage::CreateInMemory();
  ASSERT_TRUE(stage);
  const pxr::UsdShadeMaterial material = pxr::UsdShadeMaterial::Define(
      stage, pxr::SdfPath("/Looks/SeparateVector2"));
  const auto shader = [&](const char *name) {
    return pxr::UsdShadeShader::Define(stage, material.GetPath().AppendChild(pxr::TfToken(name)));
  };

  pxr::UsdShadeShader separate = shader("Separate");
  separate.CreateIdAttr(pxr::VtValue(pxr::TfToken("ND_separate2_vector2")));
  separate.CreateInput(pxr::TfToken("in"), pxr::SdfValueTypeNames->Float2)
      .Set(pxr::GfVec2f(10.125f, 11.125f));
  separate.CreateOutput(pxr::TfToken("outx"), pxr::SdfValueTypeNames->Float);
  separate.CreateOutput(pxr::TfToken("outy"), pxr::SdfValueTypeNames->Float);

  pxr::UsdShadeShader combine = shader("Combine");
  combine.CreateIdAttr(pxr::VtValue(pxr::TfToken("ND_combine2_vector2")));
  ASSERT_TRUE(combine.CreateInput(pxr::TfToken("in1"), pxr::SdfValueTypeNames->Float)
                  .ConnectToSource(separate.ConnectableAPI(), pxr::TfToken("outx")));
  ASSERT_TRUE(combine.CreateInput(pxr::TfToken("in2"), pxr::SdfValueTypeNames->Float)
                  .ConnectToSource(separate.ConnectableAPI(), pxr::TfToken("outy")));
  combine.CreateOutput(pxr::TfToken("out"), pxr::SdfValueTypeNames->Float2);

  pxr::UsdShadeShader surface = shader("Surface");
  surface.CreateIdAttr(pxr::VtValue(pxr::TfToken("ND_convert_vector2_surfaceshader")));
  ASSERT_TRUE(surface.CreateInput(pxr::TfToken("in"), pxr::SdfValueTypeNames->Float2)
                  .ConnectToSource(combine.ConnectableAPI(), pxr::TfToken("out")));
  surface.CreateOutput(pxr::TfToken("out"), pxr::SdfValueTypeNames->Token);
  const pxr::TfToken context("mtlx", pxr::TfToken::Immortal);
  ASSERT_TRUE(material.CreateSurfaceOutput(context).ConnectToSource(surface.ConnectableAPI(),
                                                                    pxr::TfToken("out")));

  materialx::Graph graph;
  string error;
  ASSERT_TRUE(materialx::read_usdshade_graph(material, &graph, &error)) << error;
  const auto read_separate = std::find_if(graph.nodes.begin(), graph.nodes.end(), [](const materialx::Node &node) {
    return node.name == "Separate";
  });
  ASSERT_NE(read_separate, graph.nodes.end());
  EXPECT_EQ(read_separate->vector2_inputs.at("in"), make_float2(10.125f, 11.125f));
  EXPECT_TRUE(read_separate->links.empty());

  ShaderGraph lowered;
  ASSERT_TRUE(materialx::lower(graph, &lowered));
}

